(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18 + Math.cos(y*0.012-t*0.18)*12 + Math.sin((x+y)*0.008+t*0.1)*8;
  const w1y = Math.cos(y*0.018-t*0.22)*18 + Math.sin(x*0.015+t*0.28)*12 + Math.cos((x-y)*0.01-t*0.15)*8;
  const sx = x+w1x, sy = y+w1y;
  const w2x = Math.sin(sx*0.025+t*0.15)*10 + Math.cos(sy*0.02-t*0.12)*7;
  const w2y = Math.cos(sy*0.022-t*0.18)*10 + Math.sin(sx*0.018+t*0.2)*7;
  const fx = sx+w2x, fy = sy+w2y;
  const src = [
    [160+Math.sin(t*0.5)*100,80+Math.cos(t*0.35)*50,0.08,2.0,1.0],
    [320+Math.cos(t*0.45)*100,160+Math.sin(t*0.6)*50,0.1,1.7,0.8],
    [240+Math.sin(t*0.28+2)*140,120+Math.cos(t*0.42+1)*90,0.06,2.3,1.2],
    [120+Math.cos(t*0.7+1)*80,180+Math.sin(t*0.55+3)*60,0.12,1.5,0.7],
    [360+Math.sin(t*0.38+4)*90,60+Math.cos(t*0.8+2)*70,0.07,2.6,0.9],
    [240+Math.cos(t*0.32+5)*120,200+Math.sin(t*0.48)*80,0.09,1.9,1.1],
    [80+Math.sin(t*0.6+3)*70,40+Math.cos(t*0.5+1)*60,0.11,2.1,0.6],
    [400+Math.cos(t*0.4+2)*60,220+Math.sin(t*0.65+4)*50,0.13,1.8,1.3],
    [200+Math.sin(t*0.55+1)*90,30+Math.cos(t*0.7+3)*40,0.05,2.4,0.85]
  ];
  let aS=0,iS=0,cross=0;
  for(const[sX,sY,f,sp,amp]of src){
    const d=Math.sqrt((fx-sX)**2+(fy-sY)**2);
    const a=Math.sin(d*f-t*sp)*amp, b=Math.sin(d*f*0.7+t*sp*0.6+1.5)*amp;
    aS+=a; iS+=b; cross+=a*b*0.3;
  }
  const n=src.length, act=aS/n, inh=iS/n, crs=cross/n;
  const bg1=(Math.sin(fx*0.035+fy*0.022+t*0.7)+Math.sin(fx*0.028-fy*0.038+t*1.0))/2;
  const bg2=Math.sin((fx+fy)*0.1+t*2.2)*0.3+Math.sin((fx-fy)*0.08-t*1.8)*0.3;
  const bg3=Math.sin(fx*0.06+fy*0.04-t*0.5)*Math.cos(fx*0.04-fy*0.05+t*0.6)*0.4;
  const bg=bg1+bg2+bg3;
  const dist=Math.sqrt((fx-cx)**2+(fy-cy)**2), ang=Math.atan2(fy-cy,fx-cx);
  const spiral=(Math.sin(dist*0.045-ang*3-t*1.3)+Math.sin(dist*0.035+ang*4.5-t*1.0))*0.35+Math.sin(dist*0.08-ang*2+t*2.0)*0.2;
  const cell1=Math.sin(fx*0.14)*Math.sin(fy*0.14)+Math.sin((fx+fy)*0.09+t)*0.4;
  const cell2=Math.sin(fx*0.08+fy*0.06-t*0.3)*Math.cos(fx*0.05-fy*0.07+t*0.4);
  const cell=Math.tanh((cell1+cell2*0.5)*1.4)*0.25;
  const detail=(Math.sin(fx*0.3+t*3)*Math.sin(fy*0.25-t*2.5)+Math.sin(fx*0.2-fy*0.15+t*2))*0.15;
  const rd=Math.tanh((act-inh*0.65+bg*0.25+spiral+crs*0.5)*2.0);
  const blend=rd*0.6+cell*0.2+detail*0.1+spiral*0.1, v=blend*0.5+0.5;
  const pal=[[5,12,45],[12,45,85],[18,85,105],[25,130,120],[80,165,100],[180,190,70],[220,180,55],[230,140,60],[210,90,65],[180,50,70],[120,30,75],[60,18,55],[20,10,42],[5,12,45]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.75+Math.sin(rd*Math.PI)*0.25, edge=Math.abs(rd)>0.65?1.12:1.0, glow=Math.max(0,1-Math.abs(rd)*1.5)*0.08;
  const fl=lum*edge+glow;
  return[Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*fl)|0,Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*fl)|0,Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*fl)|0];
}
